import {captureCalculation} from './material-notebook.js?v=20261113-support1';
import {esc,num,table} from './response-views.js?v=20261110-en1';
let latest=null;
export const getAuditResult=()=>latest;
export function renderAuditView({container,run,cancelRun,download,onLocation=()=>{}}){
 latest=null;let ticket=0;
 container.innerHTML=`<div class="obs-page connections-page"><header class="obs-header"><span class="obs-eyebrow">MODEL · STATE · MEASUREMENT</span><h2>Three-level symmetry diagnostics workshop</h2><p>uses the same two-level model to examine the Hamiltonian, state and measurement probe respectively. It can be accessed from any computing tool and the evidence can be included in the material research record.</p></header><section class="ct-panel"><div class="obs-formula">H = h_x σ_x + h_z σ_z</div><div class="obs-formula">ρ = (I + r n·σ)/2</div><p>state direction and the probe direction are both in the xz plane, and the angle is measured from +z to +x; the instantaneous state is not required to be the equilibrium state of H.</p><form id="audit-form"><label>Operation<select id="audit-operation"><option value="z">σz unitary transformation</option><option value="time">Spin 1/2 time reversal iσy K</option></select></label><div class="cn-audit-controls">${[['hx','hₓ',1,-2,2],['hz','h_z',0,-2,2],['stateAngle',"State direction angle (degrees)",0,-180,180],['probeAngle',"Probe direction angle (degrees)",90,-180,180],['polarization',"Bloch vector length r",1,0,1]].map(([k,t,v,min,max])=>`<label>${t}<input id="audit-${k}" type="number" required step="any" min="${min}" max="${max}" value="${v}"></label>`).join('')}</div><button class="primary" type="submit" id="audit-run">Check three-layer symmetry</button><button class="secondary" type="button" id="audit-cancel">Cancel</button></form><div id="audit-result" role="status">Run the default example first: H does not retain σz, while the selected state retains σz, and the expectation of the odd probe is still forced to zero.</div></section><div class="obs-links"><a href="#classroom/foundations?module=statistics">Same particle and symbol steps →</a><a href="#classroom/structure-dynamics?module=defects">Defects and Counterexamples →</a><a href="#classroom/observables?module=reciprocity">response constraints →</a><a href="#atlas/compare">parameter comparison →</a><a href="#atlas/notebook">Save material research records →</a></div></div>`;
 const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;
 onLocation("Computing Center/Three-Layer Symmetry Diagnosis Workshop");
 const invalidate=()=>{ticket++;latest=null;cancelRun?.();$('#audit-run').disabled=false;$('#audit-result').textContent="The parameters have changed, please recheck.";};$('#audit-form').oninput=invalidate;$('#audit-cancel').onclick=invalidate;
 $('#audit-form').onsubmit=async e=>{e.preventDefault();const id=++ticket,input=Object.fromEntries(['hx','hz','stateAngle','probeAngle','polarization'].map(k=>[k,Number($('#audit-'+k).value)]));input.operation=$('#audit-operation').value;latest=null;$('#audit-run').disabled=true;$('#audit-result').textContent="Running Python diagnostic...";try{const r=await run('symmetry_audit',input);if(!current()||id!==ticket)return;latest={module:'audit',input,result:r};captureCalculation('symmetry_audit',input,r,{route:'compute/symmetry-audit',title:"Three-level symmetry diagnostics"});$('#audit-result').innerHTML=table(["Level/Conclusion","Residual or result"],[["model H",num(r.hamiltonian)],["status ρ",num(r.state)],["probe O",num(r.probe)],["Probe is odd",r.probeOdd?"Yes":"No"],["expected value",num(r.expectation)],["This symmetry is forced to zero",r.forcedZero?"Yes":"No"]])+`<p>${esc(r.note)}</p><button id="audit-export" class="secondary">Export diagnostic evidence JSON</button>`;$('#audit-export').onclick=()=>download?.(JSON.stringify(latest,null,2),'symmetry-audit.json','application/json');}catch(e){if(current()&&id===ticket)$('#audit-result').textContent=e.message;}finally{if(current()&&id===ticket)$('#audit-run').disabled=false;}};
}
